CREATE OR REPLACE FUNCTION public.audit_row_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE o jsonb := CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END; n jsonb := CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END;
BEGIN
  o := o - ARRAY['national_id_no','phone_number','email','religion','ethnicity']; n := n - ARRAY['national_id_no','phone_number','email','religion','ethnicity'];
  INSERT INTO audit_log(woreda_id, actor_user_id, entity_name, entity_id, action_type, old_value_json, new_value_json, action_at)
  VALUES (COALESCE(n->>'woreda_id', o->>'woreda_id')::uuid, auth.uid(), TG_TABLE_NAME, COALESCE(n,o)->>TG_ARGV[0], 'ROW_'||TG_OP, o, n, now());
  RETURN NULL; END $$;
